ReplacementContent:
"                              {selectedTable && (
                                 <button onClick={() => {
                                    if (selectedTable) {
                                       setTableCarts(prev => ({ ...prev, [selectedTable.id]: cart }));
                                       setTableWaiters(prev => ({ ...prev, [selectedTable.id]: selectedWaiter }));
                                       setTableDiscounts(prev => ({ ...prev, [selectedTable.id]: discount }));
                                       setTableAdditionalCharges(prev => ({ ...prev, [selectedTable.id]: appliedAdditionalCharges }));
                                       setTableCustomers(prev => ({
                                          ...prev,
                                          [selectedTable.id]: {
                                             customerCountryCode,
                                             customerPhone,
                                             customerName,
                                             customerAddress,
                                             selectedCustomer,
                                             redeemedPoints,
                                             appliedCoupon,
                                             couponCode
                                          }
                                       }));
                                    }
                                    setSelectedTable(null);
                                    setCart([]);
                                    resetCustomerState();
                                 }} className="text-[9px] text-red-500 hover:text-red-600 transition-colors uppercase font-black">Clear Selection</button>
                              )}"
